// src/db.js
const all=async(db,sql,...args)=>(await db.prepare(sql).bind(...args).all()).results;
const first=async(db,sql,...args)=>db.prepare(sql).bind(...args).first();
const run=(db,sql,...args)=>db.prepare(sql).bind(...args).run();
const statement=(db,sql,...args)=>db.prepare(sql).bind(...args);
async function stage(db,runId,kind,key,data) {
  await run(db,'INSERT INTO stage(run_id,kind,key,data) VALUES(?,?,?,?) ON CONFLICT(run_id,kind,key) DO UPDATE SET data=excluded.data',runId,kind,key,JSON.stringify(data));
}

async function stageMany(db,runId,kind,items) {
  // One SQL query per bounded page, rather than one per item. A 100-contact
  // page otherwise exceeds the Free-plan limit of 50 D1 queries per invocation.
  for(let i=0;i<items.length;i+=250){
    await run(db,`INSERT INTO stage(run_id,kind,key,data)
      SELECT ?,?,json_extract(value,'$.key'),json_extract(value,'$.data') FROM json_each(?) WHERE true
      ON CONFLICT(run_id,kind,key) DO UPDATE SET data=CASE WHEN excluded.kind='contact'
      THEN json_set(excluded.data,'$.undated',MAX(COALESCE(json_extract(stage.data,'$.undated'),0),COALESCE(json_extract(excluded.data,'$.undated'),0)))
      ELSE excluded.data END`,runId,kind,JSON.stringify(items.slice(i,i+250)));
  }
}

async function stageMissingAds(db,runId,metrics){
  for(let i=0;i<metrics.length;i+=250){
    const rows=metrics.slice(i,i+250).map(m=>({key:m.adId,data:{id:m.adId,name:m.adName,campaignId:m.campaignId,campaignName:m.campaignName,adsetId:m.adsetId,adsetName:m.adsetName,status:null,format:null,attribution:null,preview:null}}));
    await run(db,`INSERT OR IGNORE INTO stage(run_id,kind,key,data)
      SELECT ?,'ad',json_extract(value,'$.key'),json_extract(value,'$.data') FROM json_each(?)`,runId,JSON.stringify(rows));
  }
}


// src/connectors/http.js
// This module is the ONLY upstream transport. No method parameter is accepted.
class UpstreamError extends Error {
  constructor(code,retryAfter=0) { super(code);this.retryAfter=retryAfter; }
}
async function readJSON(url, {origin,token,headers={},auth='bearer',expectedVersion=null,fetcher=fetch}) {
  const u=new URL(url);
  if(u.origin!==origin || u.protocol!=='https:' || u.username || u.password || u.searchParams.has('access_token')) throw new UpstreamError('UPSTREAM_ORIGIN_BLOCKED');
  if(!['bearer','api_access_token'].includes(auth))throw new UpstreamError('UPSTREAM_AUTH_SCHEME_BLOCKED');
  const credential=auth==='api_access_token'?{api_access_token:token}:{Authorization:`Bearer ${token}`};
  let response;
  // Workers does not support redirect:'error'. Manual mode never follows the
  // redirect; reject the response before reading it or forwarding credentials.
  try { response=await fetcher(u.href,{method:'GET',redirect:'manual',headers:{Accept:'application/json',...headers,...credential},signal:AbortSignal.timeout(25000)}); }
  catch { throw new UpstreamError('UPSTREAM_NETWORK_ERROR'); }
  if(response.status>=300&&response.status<400)throw new UpstreamError('UPSTREAM_REDIRECT_BLOCKED');
  if (!response.ok) {
    const retry=Math.min(3600,Math.max(0,Number(response.headers.get('retry-after'))||0));
    throw new UpstreamError(`UPSTREAM_HTTP_${response.status}`,retry);
  }
  if(expectedVersion&&response.headers.get('facebook-api-version')!==expectedVersion)throw new UpstreamError('UPSTREAM_API_VERSION_MISMATCH');
  if (Number(response.headers.get('content-length'))>12000000) throw new UpstreamError('UPSTREAM_RESPONSE_TOO_LARGE');
  // Do not log response bodies: CRM data may contain health information.
  let data;try { data=await response.json(); } catch {throw new UpstreamError('UPSTREAM_INVALID_JSON');}
  if(data?.error) throw new UpstreamError('UPSTREAM_API_ERROR');
  return data;
}
function nextCursor(data,origin,accountId) {
  const next=data?.paging?.next;
  if(!next) return null;
  const u=new URL(next);
  if(u.origin!==origin || !u.pathname.includes(`/act_${accountId}/`)) throw new UpstreamError('META_PAGINATION_SCOPE_BLOCKED');
  const after=data?.paging?.cursors?.after || u.searchParams.get('after');
  if(!after || after.length>4000) throw new UpstreamError('META_INVALID_CURSOR');
  // Never persist paging.next, which may contain an access token.
  return after;
}


